SRN_st.name='SRN'; 
SRN_st.lat=30.32;
SRN_st.lon=78.41;
SRN_st.alt=0000;
SRN_st.env='Mt';
SRN_st.footp='RB';
%%
% data imported via the import tool from matlab
 SRN_rd_h = importfile_AE_India("C:\github_trend\raw_data\Aethalometer_India\Aethalometer\SRN_2016-2026_Hour.csv", [2, Inf]);
SRN_rd_h.Properties.DimensionNames{1}='Time';
SRN_rd_h.Properties.VariableNames{2}='Ba1_A';
SRN_rd_h.Properties.VariableNames{3}='Ba2_A';
SRN_rd_h.Properties.VariableNames{4}='Ba3_A';
SRN_rd_h.Properties.VariableNames{5}='Ba4_A';
SRN_rd_h.Properties.VariableNames{6}='Ba5_A';
SRN_rd_h.Properties.VariableNames{7}='Ba6_A';
SRN_rd_h.Properties.VariableNames{8}='Ba7_A';
names_rd=fieldnames(SRN_rd_h);
%%
SRN_rd=retime(SRN_rd_h,'daily',@nanmedian);
%%
datevec(SRN_rd.Time(1)) % begin in 2016,  %[output:7a3f5d0a]
datevec(SRN_rd.Time(end)) % end in 2026 April %[output:0c280ed0]
plotFigControl(SRN_rd,SRN_st.name);  %[output:7030742d] %[output:92f916c9] %[output:8a3db4cb] %[output:0941217c] %[output:81f161b9] %[output:7911ff20] %[output:977cd030] %[output:04cba172]
%%
lambdaAE7=[370 470 520 590 660 880 950];
%compute abs exp
Ca3=startsWith(names_rd,{'Ba'}) & contains(names_rd,{'_A'});
names_abs=names_rd(Ca3);
SRN_cal=compute_exp_D(SRN_rd,names_abs,lambdaAE7); %[output:7c63b252] %[output:600ff552] %[output:829f7b86] %[output:8d72d593] %[output:386bcdcd] %[output:16b23c32] %[output:98fc09fa] %[output:9027f3bf] %[output:949d32bd] %[output:5ec64117] %[output:996f024b] %[output:10414695] %[output:19278f3d] %[output:0eba1183]
plotFigControl_cal(SRN_cal,SRN_st.name); %[output:61434ad4] %[output:15dee4cb] %[output:3ad61939]
%%
%HOMOGENEITY

break_SRN_abs_BP=change_point_analysis_Def(SRN_rd,names_abs,0.05,'SRN','Absorption'); %[output:6b7ee9f8] %[output:5a393386] %[output:85ed12d1] %[output:4eb1a59d] %[output:9f80f676] %[output:5bc73f83]
T_SRN_abs_BP=make_table_breakpoints_def(break_SRN_abs_BP);

names_expA={'expA_bgAE','expA_brAE','expA_grAE','expA_fit'} %[output:90092b60]
break_SRN_expA_BP=change_point_analysis_Def(SRN_cal,names_expA,0.05,'SRN','Absorption exponent'); %[output:776eecee] %[output:91fe9fa3] %[output:9f6c0857] %[output:89fee263]
T_SRN_expA_BP=make_table_breakpoints_def(break_SRN_expA_BP);




